=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements interface_spec.md per microarchitecture.md.
// Zero wait states, PSLVERR for unmapped addresses, synchronous active-low reset.
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                      pclk,
    input  wire                      presetn,
    input  wire [ADDR_WIDTH-1:0]     paddr,
    input  wire                      psel,
    input  wire                      penable,
    input  wire                      pwrite,
    input  wire [DATA_WIDTH-1:0]     pwdata,
    input  wire [(DATA_WIDTH/8)-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]     prdata,
    output wire                      pready,
    output wire                      pslverr
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;

    // ------------------------------------------------------------------
    // Register state
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    // ------------------------------------------------------------------
    // Access phase and address decode
    // ------------------------------------------------------------------
    wire access = psel && penable;

    // Mapped: word aligned and within 0x0..0xC.
    wire mapped = (paddr[1:0] == 2'b00) &&
                  (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

    wire wr_access = access && pwrite  && mapped;
    wire rd_access = access && !pwrite && mapped;

    wire we0 = wr_access && (paddr[3:2] == 2'd0);
    wire we1 = wr_access && (paddr[3:2] == 2'd1);
    wire we2 = wr_access && (paddr[3:2] == 2'd2);
    wire we3 = wr_access && (paddr[3:2] == 2'd3);

    // ------------------------------------------------------------------
    // Byte-strobe merge
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] wmask;
    genvar b;
    generate
        for (b = 0; b < STRB_WIDTH; b = b + 1) begin : g_wmask
            assign wmask[8*b +: 8] = {8{pstrb[b]}};
        end
    endgenerate

    wire [DATA_WIDTH-1:0] reg0_d = (reg0 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] reg1_d = (reg1 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] reg2_d = (reg2 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] reg3_d = (reg3 & ~wmask) | (pwdata & wmask);

    // ------------------------------------------------------------------
    // Register file: synchronous active-low reset, load on write access
    // ------------------------------------------------------------------
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            if (we0) reg0 <= reg0_d;
            if (we1) reg1 <= reg1_d;
            if (we2) reg2 <= reg2_d;
            if (we3) reg3 <= reg3_d;
        end
    end

    // ------------------------------------------------------------------
    // Read data: combinational mux, zero unless mapped read access
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] rd_mux;
    always @* begin
        case (paddr[3:2])
            2'd0:    rd_mux = reg0;
            2'd1:    rd_mux = reg1;
            2'd2:    rd_mux = reg2;
            default: rd_mux = reg3;
        endcase
    end

    assign prdata  = rd_access ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

`ifdef FORMAL
    // Design-intent properties (unproven until a .sby is submitted).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    // Manager assumptions
    initial assume (!presetn);
    always @(*) if (!presetn) assume (!psel);
    always @(*) if (penable) assume (psel);
    always @(posedge pclk) begin
        if (f_past_valid && $past(presetn)) begin
            if ($past(psel && !penable)) begin
                assume (psel && penable);
                assume (paddr  == $past(paddr));
                assume (pwrite == $past(pwrite));
                assume (pwdata == $past(pwdata));
                assume (pstrb  == $past(pstrb));
            end
            if ($past(psel && penable)) assume (!penable);
        end
    end

    // Independent decode
    wire f_mapped = (paddr < 16) && (paddr[1:0] == 2'b00);
    reg [DATA_WIDTH-1:0] f_reg;
    always @(*) begin
        case (paddr[3:2])
            2'd0:    f_reg = reg0;
            2'd1:    f_reg = reg1;
            2'd2:    f_reg = reg2;
            default: f_reg = reg3;
        endcase
    end

    always @(*) begin
        assert (pready);
        if (!(psel && penable)) begin
            assert (prdata == {DATA_WIDTH{1'b0}});
            assert (!pslverr);
        end else begin
            assert (pslverr == !f_mapped);
            if (!pwrite && f_mapped)
                assert (prdata == f_reg);
            else
                assert (prdata == {DATA_WIDTH{1'b0}});
        end
    end

    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn)) begin
            assert (reg0 == {DATA_WIDTH{1'b0}});
            assert (reg1 == {DATA_WIDTH{1'b0}});
            assert (reg2 == {DATA_WIDTH{1'b0}});
            assert (reg3 == {DATA_WIDTH{1'b0}});
        end
    end

    wire [4*DATA_WIDTH-1:0] f_regs = {reg3, reg2, reg1, reg0};
    genvar fk, fb;
    generate
        for (fk = 0; fk < 4; fk = fk + 1) begin : g_f_reg
            for (fb = 0; fb < STRB_WIDTH; fb = fb + 1) begin : g_f_byte
                always @(posedge pclk) begin
                    if (f_past_valid && $past(presetn)) begin
                        if ($past(psel && penable && pwrite && f_mapped &&
                                  (paddr[3:2] == fk) && pstrb[fb]))
                            assert (f_regs[fk*DATA_WIDTH + 8*fb +: 8] ==
                                    $past(pwdata[8*fb +: 8]));
                        else
                            assert (f_regs[fk*DATA_WIDTH + 8*fb +: 8] ==
                                    $past(f_regs[fk*DATA_WIDTH + 8*fb +: 8]));
                    end
                end
            end
            always @(posedge pclk) begin
                cover (f_past_valid && presetn && psel && penable && !pwrite &&
                       f_mapped && (paddr[3:2] == fk) && (prdata != {DATA_WIDTH{1'b0}}));
            end
        end
    endgenerate

    always @(posedge pclk) cover (presetn && pslverr);
`endif

endmodule
`default_nettype wire
=== END FILE ===
