`timescale 1ns/1ps
// Self-checking directed testbench for apb_regs.
// Inputs are driven after the falling edge; outputs are sampled 4 ns later,
// 1 ns before the rising edge.
module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer passed;
    integer failed;
    integer i;
    integer s;
    reg [8*64-1:0] nonce;
    reg [31:0] model [0:3];
    reg [7:0]  ulist [0:15];

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ------------------------------------------------------------------
    // Reference model helpers (independent of the RTL)
    // ------------------------------------------------------------------
    function [31:0] tb_merge(input [31:0] old_v, input [31:0] d, input [3:0] st);
        integer k;
        begin
            tb_merge = old_v;
            for (k = 0; k < 4; k = k + 1)
                if (st[k]) tb_merge[8*k +: 8] = d[8*k +: 8];
        end
    endfunction

    function tb_mapped(input [7:0] a);
        begin
            tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    // ------------------------------------------------------------------
    // Checks
    // ------------------------------------------------------------------
    task check1(input got, input expv, input integer id);
        begin
            if (got === expv) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d at %0t: got %b, expected %b", id, $time, got, expv);
            end
        end
    endtask

    task check32(input [31:0] got, input [31:0] expv, input integer id);
        begin
            if (got === expv) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d at %0t: got %h, expected %h (paddr %h)", id, $time, got, expv, paddr);
            end
        end
    endtask

    task check_quiet(input integer id);
        begin
            check32(prdata, 32'h0000_0000, id);
            check1(pslverr, 1'b0, id);
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks
    // ------------------------------------------------------------------
    task idle(input integer n);
        integer c;
        begin
            for (c = 0; c < n; c = c + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                #4;
                check_quiet(100);
            end
        end
    endtask

    task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb);
        reg mapped;
        begin
            mapped = tb_mapped(addr);
            // setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = addr;
            pwdata  = data;
            pstrb   = strb;
            #4;
            check_quiet(200);
            // access phase
            @(negedge pclk);
            penable = 1'b1;
            #4;
            check1(pready, 1'b1, 201);
            check1(pslverr, ~mapped, 202);
            check32(prdata, 32'h0000_0000, 203);
            if (mapped)
                model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
        end
    endtask

    task apb_read(input [7:0] addr);
        reg        mapped;
        reg [31:0] expv;
        begin
            mapped = tb_mapped(addr);
            expv   = mapped ? model[addr[3:2]] : 32'h0000_0000;
            // setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = addr;
            pwdata  = 32'hFFFF_FFFF;
            pstrb   = 4'h0;
            #4;
            check_quiet(300);
            // access phase
            @(negedge pclk);
            penable = 1'b1;
            #4;
            check1(pready, 1'b1, 301);
            check1(pslverr, ~mapped, 302);
            check32(prdata, expv, 303);
        end
    endtask

    task read_all;
        begin
            apb_read(8'h00);
            apb_read(8'h04);
            apb_read(8'h08);
            apb_read(8'h0C);
        end
    endtask

    // ------------------------------------------------------------------
    // Stimulus
    // ------------------------------------------------------------------
    initial begin
        passed  = 0;
        failed  = 0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0000_0000;
        pstrb   = 4'h0;
        presetn = 1'b0;
        for (i = 0; i < 4; i = i + 1) model[i] = 32'h0000_0000;

        ulist[0]  = 8'h01; ulist[1]  = 8'h02; ulist[2]  = 8'h03; ulist[3]  = 8'h05;
        ulist[4]  = 8'h06; ulist[5]  = 8'h07; ulist[6]  = 8'h0D; ulist[7]  = 8'h0E;
        ulist[8]  = 8'h0F; ulist[9]  = 8'h10; ulist[10] = 8'h14; ulist[11] = 8'h1C;
        ulist[12] = 8'h40; ulist[13] = 8'h80; ulist[14] = 8'hFC; ulist[15] = 8'hFF;

        // 1. Reset: outputs quiet
        repeat (3) begin
            @(negedge pclk);
            #4;
            check_quiet(10);
        end
        @(negedge pclk);
        presetn = 1'b1;
        #4;
        check_quiet(11);
        idle(2);

        // 2. Reset values, back to back
        read_all;
        idle(1);

        // 3. Write then read every register (back to back)
        apb_write(8'h00, 32'hA5A5_0001, 4'hF);
        apb_write(8'h04, 32'h5A5A_0002, 4'hF);
        apb_write(8'h08, 32'hDEAD_BEEF, 4'hF);
        apb_write(8'h0C, 32'h0123_4567, 4'hF);
        apb_read(8'h0C);
        apb_read(8'h08);
        apb_read(8'h04);
        apb_read(8'h00);

        // 4. Every strobe pattern on REG2, including none
        for (s = 0; s < 16; s = s + 1) begin
            apb_write(8'h08, 32'hC3C3_C3C3 ^ (s * 32'h0101_0101), s[3:0]);
            apb_read(8'h08);
        end

        // 5. Single and mixed lanes on REG0 and REG3
        apb_write(8'h00, 32'hFFFF_FFFF, 4'b0001);
        apb_read(8'h00);
        apb_write(8'h00, 32'h7777_7777, 4'b1000);
        apb_read(8'h00);
        apb_write(8'h0C, 32'hAAAA_AAAA, 4'b0110);
        apb_read(8'h0C);
        apb_write(8'h0C, 32'h5555_5555, 4'b1001);
        apb_read(8'h0C);
        read_all;

        // 6. Idle gaps between transfers
        apb_write(8'h04, 32'hCAFE_F00D, 4'hF);
        idle(3);
        apb_read(8'h04);
        idle(1);
        apb_read(8'h00);
        idle(2);

        // 7. Back-to-back write then read of the same register
        apb_write(8'h0C, 32'h8765_4321, 4'hF);
        apb_read(8'h0C);
        apb_write(8'h0C, 32'h1111_2222, 4'b0011);
        apb_read(8'h0C);

        // 8. Unmapped writes: PSLVERR and no register change
        for (i = 0; i < 16; i = i + 1)
            apb_write(ulist[i], 32'hFFFF_FFFF, 4'hF);
        read_all;

        // 9. Unmapped reads: zero data with PSLVERR
        for (i = 0; i < 16; i = i + 1)
            apb_read(ulist[i]);

        // 10. Mixed mapped and unmapped, back to back
        apb_write(8'h10, 32'h0BAD_0BAD, 4'hF);
        apb_read(8'h00);
        apb_read(8'h11);
        apb_write(8'h00, 32'h600D_600D, 4'hF);
        apb_read(8'h00);
        idle(2);

        // 11. Reset again (manager keeps psel low)
        @(negedge pclk);
        psel    = 1'b0;
        penable = 1'b0;
        presetn = 1'b0;
        for (i = 0; i < 4; i = i + 1) model[i] = 32'h0000_0000;
        #4;
        check_quiet(12);
        repeat (2) begin
            @(negedge pclk);
            #4;
            check_quiet(13);
        end
        @(negedge pclk);
        presetn = 1'b1;
        #4;
        check_quiet(14);
        idle(1);
        read_all;
        apb_write(8'h04, 32'h1357_9BDF, 4'hF);
        apb_read(8'h04);
        idle(2);

        // Verdict
        nonce = {8*64{1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {8*64{1'b0}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
